<!-- Generated by design-ui/bin/generate-review-demos.mjs; fixture: basic.vue. Edit the authored scenario, then regenerate. -->
<script setup lang="ts">
import { computed, onBeforeUnmount, onDeactivated, ref } from 'vue'
import { watchLang } from '@maple-design/cli-vue/client'
import type { InfiniteScrollStatus } from '@maple-design/ui-vue'
import { defineReviewConfig, ReviewSlot as DemoReviewSlot } from '@sparknest/ui-doc-preview-vue'
import DemoApiReviewPanel from '../../../../docs/components/ApiReviewPanel.vue'
import __apiReviewRawConfig from './api-review.config.json'

const scroller = ref<HTMLElement>()
const status = ref<InfiniteScrollStatus>('idle')
let timer: ReturnType<typeof setTimeout> | undefined
const items = ref<number[]>([])
const language = ref('zh-CN')
const english = computed(() => language.value === 'en-US')

watchLang((value) => {
  language.value = value
})

function load() {
  clearTimeout(timer)
  timer = setTimeout(() => {
    timer = undefined
    for (let index = 0; index < 12; index++) {
      items.value.push(items.value.length + 1)
    }
    status.value = items.value.length >= 60 ? 'finished' : 'idle'
  }, 500)
}
onBeforeUnmount(() => clearTimeout(timer))
onDeactivated(() => {
  clearTimeout(timer)
  timer = undefined
  if (status.value === 'loading') {
    status.value = 'idle'
  }
})
</script>

<template>
  <DemoApiReviewPanel v-slot="__apiReview" v-bind="defineReviewConfig(__apiReviewRawConfig)">
    <div ref="scroller" class="infinite-scroll-demo">
      <mp-infinite-scroll
        v-model:status="status"
        :target="scroller"
        :bottom-offset="24"
        v-bind="__apiReview.bindings"
        @load="load"
        v-on="__apiReview.listeners"
      >
        <mp-cell v-for="item in items" :key="item">{{ english ? 'List item' : '列表项' }} {{ item }}</mp-cell>
        <template v-if="__apiReview.slotEnabled['loading']" #loading="__reviewSlot"
          ><DemoReviewSlot
            name="loading"
            :context="__reviewSlot"
            :controls="__apiReview.controls"
            :record="__apiReview.record"
        /></template>
        <template v-if="__apiReview.slotEnabled['error']" #error="__reviewSlot"
          ><DemoReviewSlot
            name="error"
            :context="__reviewSlot"
            :controls="__apiReview.controls"
            :record="__apiReview.record"
        /></template>
        <template v-if="__apiReview.slotEnabled['finished']" #finished="__reviewSlot"
          ><DemoReviewSlot
            name="finished"
            :context="__reviewSlot"
            :controls="__apiReview.controls"
            :record="__apiReview.record" /></template
      ></mp-infinite-scroll>
    </div>
  </DemoApiReviewPanel>
</template>

<style scoped>
.infinite-scroll-demo {
  height: 280px;
  overflow-y: auto;
  background: var(--mp-color-bg-1);
